import{_ as r,C as a,c as l,o,aa as n,G as i}from"./chunks/framework.Cn7WEiMX.js";const m=JSON.parse('{"title":"类型键","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"terra-api","link":"/wiki/Terra/terra-api"},{"title":"api-concepts","link":"/wiki/Terra/terra-api/api-concepts"},{"title":"类型键","link":"/wiki/Terra/terra-api/api-concepts/type-keys"}]},"headers":[],"relativePath":"wiki/Terra/terra-api/api-concepts/type-keys.md","filePath":"wiki/Terra/terra-api/api-concepts/type-keys.md"}'),p={name:"wiki/Terra/terra-api/api-concepts/type-keys.md"};function c(h,e,d,k,y,g){const t=a("NolebaseGitContributors"),s=a("NolebaseGitChangelog");return o(),l("div",null,[e[0]||(e[0]=n('<h1 id="类型键" tabindex="-1">类型键 <a class="header-anchor" href="#类型键" aria-label="Permalink to &quot;类型键&quot;">​</a></h1><p>Terra API 的许多地方都用到了泛型与 Java 的 <a href="https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/lang/Class.html" target="_blank" rel="noreferrer">Class</a> 类，用于确保反射类型处理的类型安全。通常情况下，这个方法颇有成效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>如果你需要注册了 <code>SomeObject&lt;SomeOtherThing&gt;</code> 实例的注册条目怎么办？因为有<a href="https://www.baeldung.com/java-type-erasure" target="_blank" rel="noreferrer">类型擦除</a>的存在，这无法直接实现。你不能直接访问不存在于运行时的 <code>SomeObject&lt;SomeOtherThing&gt;.class</code>。</p><p>一种解决方案是使用 <code>SomeObject.class</code>，但它并非最佳选择，理由有二：</p><ul><li>它会破坏类型安全、<code>SomeObject</code> 不再会有泛型类型。</li><li>它会覆盖某些东西，或者被尝试注册任何 <code>SomeObject</code> 泛型类型的东西覆盖。</li></ul><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>Terra 引入了一种叫做 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/util/reflection/TypeKey.html" target="_blank" rel="noreferrer">TypeKey</a> 的抽象类解决这个问题。所有接受 <code>Class</code> 实例的 API 同样接受 <code>TypeKey</code>。</p><h2 id="获取类型键" tabindex="-1">获取类型键 <a class="header-anchor" href="#获取类型键" aria-label="Permalink to &quot;获取类型键&quot;">​</a></h2><p>为了让你的类型获取 <code>TypeKey</code> 实例，只需创建继承了 <code>TypeKey</code> 的注释内部类，同时泛型类型与你的相符。在我们的 <code>SomeObject&lt;SomeOtherThing&gt;</code> 示例中，代码如下：</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeKey&lt;SomeObject&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SomeOtherThing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt; SOME_OBJECT_SOME_OTHER_THING_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeKey&lt;&gt;() { };</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">信息</p><p>注意，<code>TypeKey</code> 是 <code>static final</code> 的。将键声明移动到类顶部可以减少对其的引用，并减少不必要的实例化。</p></div><h3 id="从类实例获取类型键" tabindex="-1">从类实例获取类型键 <a class="header-anchor" href="#从类实例获取类型键" aria-label="Permalink to &quot;从类实例获取类型键&quot;">​</a></h3><p>为了进一步降低重复引用，你可以直接从 <a href="https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/lang/Class.html" target="_blank" rel="noreferrer">Class</a> 实例通过 <a href="https://ci.codemc.io/job/PolyhedralDev/job/Terra/javadoc/com/dfsek/terra/api/util/reflection/TypeKey.html#of-java.lang.Class-" target="_blank" rel="noreferrer">TypeKey#of(Class)</a> 获取 TypeKey。如果你需要某个非泛型类型的 TypeKey，这会很有用。</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TypeKey</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Something</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeKey.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Something.class);</span></span></code></pre></div>',15)),i(t),i(s)])}const T=r(p,[["render",c]]);export{m as __pageData,T as default};
